#!/usr/bin/env python3
"""Defensive, offline QUIC v1 trace auditor (finite synthetic model).

Reads one UTF-8 JSON request document on stdin, writes one JSON response
document on stdout.  Any invalid input yields exactly {"error":"INVALID_INPUT"}.
"""

import json
import re
import sys

MAXN = 4611686018427387903
CSIZE = 1024
MAX_TRACES = 32
MAX_EVENTS = 20000
MAX_PACKETS = 20000
MAX_FRAMES = 60000
MAX_FRAME_DATA = 2 * 1024 * 1024
MAX_REQUEST = 16 * 1024 * 1024

_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}")
_HEX_RE = re.compile(r"[0-9a-f]*")

# frame name -> levels in which the frame is permitted (CLOSE handled apart)
_ALLOWED = {
    "PADDING": "IHZA",
    "PING": "IHZA",
    "ACK": "IHA",
    "CRYPTO": "IHA",
    "STREAM": "ZA",
    "RESET_STREAM": "ZA",
    "STOP_SENDING": "ZA",
    "HANDSHAKE_DONE": "",
}

_FRAME_KEYS = {
    "PADDING": frozenset(("type",)),
    "PING": frozenset(("type",)),
    "ACK": frozenset(("type", "ranges")),
    "CRYPTO": frozenset(("type", "offset", "data_hex")),
    "STREAM": frozenset(("type", "id", "offset", "data_hex", "fin")),
    "RESET_STREAM": frozenset(("type", "id", "final_size")),
    "STOP_SENDING": frozenset(("type", "id")),
    "CLOSE": frozenset(("type", "app", "code")),
    "HANDSHAKE_DONE": frozenset(("type",)),
    "UNKNOWN": frozenset(("type",)),
}

_CFG_KEYS = frozenset((
    "early", "overlap", "buffer_packets", "idle_ms", "max_streams_bidi",
    "max_streams_uni", "max_stream_data", "max_data", "crypto_limit", "sent",
))


class Invalid(Exception):
    """Raised for any invalid input."""


# --------------------------------------------------------------------------
# strict JSON parsing
# --------------------------------------------------------------------------

def _parse(raw):
    if len(raw) > MAX_REQUEST:
        raise Invalid()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid()

    def _hook(pairs):
        obj = {}
        for key, val in pairs:
            if key in obj:
                raise Invalid()
            obj[key] = val
        return obj

    def _bad(_s):
        raise Invalid()

    try:
        return json.loads(
            text,
            object_pairs_hook=_hook,
            parse_constant=_bad,   # NaN / Infinity / -Infinity
            parse_float=_bad,      # every non-integer number
        )
    except Invalid:
        raise
    except (ValueError, TypeError, RecursionError, MemoryError):
        raise Invalid()


# --------------------------------------------------------------------------
# grammar validation
# --------------------------------------------------------------------------

def _is_int(v):
    return type(v) is int


def _is_bool(v):
    return type(v) is bool


def _check_hex(s):
    """Validate a data_hex string; return the decoded byte count."""
    if type(s) is not str:
        raise Invalid()
    n = len(s)
    if n & 1:
        raise Invalid()
    if n > 4096:
        raise Invalid()
    if _HEX_RE.fullmatch(s) is None:
        raise Invalid()
    return n >> 1


def _check_ranges_strict(rng):
    """CONFIG ranges: sorted, disjoint, nonadjacent."""
    if type(rng) is not list:
        raise Invalid()
    if len(rng) > 32:
        raise Invalid()
    prev = None
    for pair in rng:
        if type(pair) is not list or len(pair) != 2:
            raise Invalid()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise Invalid()
        if lo < 0 or hi > MAXN or lo > hi:
            raise Invalid()
        if prev is not None and lo <= prev + 1:
            raise Invalid()
        prev = hi


def _check_ranges_loose(rng):
    """Frame ACK ranges: only endpoint/length domains are input constraints."""
    if type(rng) is not list:
        raise Invalid()
    if len(rng) > 32:
        raise Invalid()
    for pair in rng:
        if type(pair) is not list or len(pair) != 2:
            raise Invalid()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise Invalid()
        if lo < 0 or hi > MAXN:
            raise Invalid()


def _validate_frame(fr):
    """Validate one frame; return its decoded data byte count."""
    if type(fr) is not dict:
        raise Invalid()
    ty = fr.get("type")
    if type(ty) is not str:
        raise Invalid()
    keys = _FRAME_KEYS.get(ty)
    if keys is None:
        raise Invalid()
    if set(fr) != keys:
        raise Invalid()
    if ty == "ACK":
        _check_ranges_loose(fr["ranges"])
        return 0
    if ty == "CRYPTO" or ty == "STREAM":
        off = fr["offset"]
        if not _is_int(off) or off < 0 or off > MAXN:
            raise Invalid()
        n = _check_hex(fr["data_hex"])
        if ty == "STREAM":
            sid = fr["id"]
            if not _is_int(sid) or sid < 0 or sid > MAXN:
                raise Invalid()
            if not _is_bool(fr["fin"]):
                raise Invalid()
        return n
    if ty == "RESET_STREAM" or ty == "STOP_SENDING":
        sid = fr["id"]
        if not _is_int(sid) or sid < 0 or sid > MAXN:
            raise Invalid()
        return 0
    if ty == "CLOSE":
        if not _is_bool(fr["app"]):
            raise Invalid()
        code = fr["code"]
        if not _is_int(code) or code < 0 or code > MAXN:
            raise Invalid()
    return 0


def _validate_config(cfg):
    if type(cfg) is not dict:
        raise Invalid()
    if set(cfg) != _CFG_KEYS:
        raise Invalid()
    if not _is_bool(cfg["early"]):
        raise Invalid()
    if cfg["overlap"] not in ("reject", "first"):
        raise Invalid()
    v = cfg["buffer_packets"]
    if not _is_int(v) or v < 0 or v > 1024:
        raise Invalid()
    v = cfg["idle_ms"]
    if not _is_int(v) or v < 0 or v > 1000000000:
        raise Invalid()
    for k in ("max_streams_bidi", "max_streams_uni"):
        v = cfg[k]
        if not _is_int(v) or v < 0 or v > 1024:
            raise Invalid()
    v = cfg["max_stream_data"]
    if not _is_int(v) or v < 0 or v > 65536:
        raise Invalid()
    v = cfg["max_data"]
    if not _is_int(v) or v < 0 or v > MAXN:
        raise Invalid()
    v = cfg["crypto_limit"]
    if not _is_int(v) or v < 0 or v > 65536:
        raise Invalid()
    sent = cfg["sent"]
    if type(sent) is not dict:
        raise Invalid()
    if set(sent) != frozenset(("I", "H", "A")):
        raise Invalid()
    for k in ("I", "H", "A"):
        _check_ranges_strict(sent[k])


def _validate(doc):
    if type(doc) is not dict:
        raise Invalid()
    if set(doc) != frozenset(("version", "traces")):
        raise Invalid()
    v = doc["version"]
    if not _is_int(v) or v != 1:
        raise Invalid()
    traces = doc["traces"]
    if type(traces) is not list:
        raise Invalid()
    if len(traces) > MAX_TRACES:
        raise Invalid()
    n_events = 0
    n_packets = 0
    n_frames = 0
    n_data = 0
    seen_ids = set()
    for tr in traces:
        if type(tr) is not dict:
            raise Invalid()
        if set(tr) != frozenset(("id", "config", "events")):
            raise Invalid()
        tid = tr["id"]
        if type(tid) is not str or _ID_RE.fullmatch(tid) is None:
            raise Invalid()
        if tid in seen_ids:
            raise Invalid()
        seen_ids.add(tid)
        _validate_config(tr["config"])
        events = tr["events"]
        if type(events) is not list:
            raise Invalid()
        n_events += len(events)
        if n_events > MAX_EVENTS:
            raise Invalid()
        prev_t = None
        for ev in events:
            if type(ev) is not dict:
                raise Invalid()
            ks = set(ev)
            if "t" not in ks or "op" not in ks:
                raise Invalid()
            t = ev["t"]
            if not _is_int(t) or t < 0 or t > 1000000000000:
                raise Invalid()
            if prev_t is not None and t < prev_t:
                raise Invalid()
            prev_t = t
            op = ev["op"]
            if op == "tick":
                if ks != frozenset(("t", "op")):
                    raise Invalid()
            elif op == "key":
                if ks != frozenset(("t", "op", "level", "action")):
                    raise Invalid()
                if ev["level"] not in ("I", "H", "Z", "A"):
                    raise Invalid()
                if ev["action"] not in ("install", "discard"):
                    raise Invalid()
            elif op == "datagram":
                if ks != frozenset(("t", "op", "bytes", "packets")):
                    raise Invalid()
                size = ev["bytes"]
                if not _is_int(size) or size < 0 or size > 65535:
                    raise Invalid()
                pkts = ev["packets"]
                if type(pkts) is not list:
                    raise Invalid()
                npk = len(pkts)
                if npk < 1 or npk > 16:
                    raise Invalid()
                n_packets += npk
                if n_packets > MAX_PACKETS:
                    raise Invalid()
                for p in pkts:
                    if type(p) is not dict:
                        raise Invalid()
                    if set(p) != frozenset(("level", "pn", "auth", "frames")):
                        raise Invalid()
                    if p["level"] not in ("I", "H", "Z", "A"):
                        raise Invalid()
                    pn = p["pn"]
                    if not _is_int(pn) or pn < 0 or pn > MAXN:
                        raise Invalid()
                    if not _is_bool(p["auth"]):
                        raise Invalid()
                    frames = p["frames"]
                    if type(frames) is not list or len(frames) > 64:
                        raise Invalid()
                    n_frames += len(frames)
                    if n_frames > MAX_FRAMES:
                        raise Invalid()
                    for fr in frames:
                        n_data += _validate_frame(fr)
                        if n_data > MAX_FRAME_DATA:
                            raise Invalid()
            else:
                raise Invalid()


# --------------------------------------------------------------------------
# byte stores
# --------------------------------------------------------------------------

class _Store(object):
    """Sparse byte store for one stream / one CRYPTO level.

    Chunks are immutable ``bytes`` objects of length 2*CSIZE: the first half
    holds data, the second half a 0/1 stored mask.  Immutability makes packet
    rollback a plain dict restore.
    """

    __slots__ = ("chunks", "contig")

    def __init__(self):
        self.chunks = {}
        self.contig = 0

    def store(self, off, data, keep_first):
        """Store ``data`` at ``off``; return "PROTOCOL_VIOLATION" on conflict."""
        chunks = self.chunks
        csize = CSIZE
        n = len(data)
        pos = 0
        while pos < n:
            a = off + pos
            base = a - (a % csize)
            idx = a - base
            take = n - pos
            room = csize - idx
            if take > room:
                take = room
            ch = chunks.get(base)
            if ch is None:
                buf = bytearray(2 * csize)
                buf[idx:idx + take] = data[pos:pos + take]
                buf[csize + idx:csize + idx + take] = b"\x01" * take
                chunks[base] = bytes(buf)
            else:
                ones = ch[csize + idx:csize + idx + take].count(1)
                if ones == 0:
                    buf = bytearray(ch)
                    buf[idx:idx + take] = data[pos:pos + take]
                    buf[csize + idx:csize + idx + take] = b"\x01" * take
                    chunks[base] = bytes(buf)
                elif ones == take:
                    if not keep_first and ch[idx:idx + take] != data[pos:pos + take]:
                        return "PROTOCOL_VIOLATION"
                else:
                    buf = bytearray(ch)
                    i = idx
                    j = pos
                    end = idx + take
                    while i < end:
                        if buf[csize + i]:
                            if not keep_first and buf[i] != data[j]:
                                return "PROTOCOL_VIOLATION"
                        else:
                            buf[i] = data[j]
                            buf[csize + i] = 1
                        i += 1
                        j += 1
                    chunks[base] = bytes(buf)
            pos += take
        return None

    def advance(self):
        """Extend the contiguous stored prefix from offset 0."""
        c = self.contig
        chunks = self.chunks
        csize = CSIZE
        while True:
            base = c - (c % csize)
            ch = chunks.get(base)
            if ch is None:
                break
            j = ch.find(0, csize + (c - base), 2 * csize)
            if j < 0:
                c = base + csize
                continue
            c = base + (j - csize)
            break
        self.contig = c

    def prefix_hex(self):
        c = self.contig
        if c == 0:
            return ""
        chunks = self.chunks
        csize = CSIZE
        parts = []
        pos = 0
        while pos < c:
            base = pos - (pos % csize)
            ch = chunks.get(base)
            if ch is None:
                break
            idx = pos - base
            take = c - pos
            room = csize - idx
            if take > room:
                take = room
            parts.append(ch[idx:idx + take])
            pos += take
        return b"".join(parts).hex()


class Stream(_Store):
    __slots__ = ("sid", "highest", "final_size", "reset", "stopped")

    def __init__(self, sid):
        _Store.__init__(self)
        self.sid = sid
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False


class Crypto(_Store):
    __slots__ = ("highest",)

    def __init__(self):
        _Store.__init__(self)
        self.highest = 0


class _Pkt(object):
    __slots__ = ("ei", "pi", "level", "pn", "auth", "frames", "arrival")

    def __init__(self, ei, pi, level, pn, auth, frames, arrival):
        self.ei = ei
        self.pi = pi
        self.level = level
        self.pn = pn
        self.auth = auth
        self.frames = frames
        self.arrival = arrival


# --------------------------------------------------------------------------
# per-trace simulation
# --------------------------------------------------------------------------

class Sim(object):
    def __init__(self, cfg):
        self.early = cfg["early"]
        self.keep_first = (cfg["overlap"] == "first")
        self.buffer_packets = cfg["buffer_packets"]
        self.idle_ms = cfg["idle_ms"]
        self.max_bidi = cfg["max_streams_bidi"]
        self.max_uni = cfg["max_streams_uni"]
        self.max_stream_data = cfg["max_stream_data"]
        self.max_data = cfg["max_data"]
        self.crypto_limit = cfg["crypto_limit"]
        self.sent = {"I": cfg["sent"]["I"], "H": cfg["sent"]["H"], "A": cfg["sent"]["A"]}
        self.keys = {
            "I": "live",
            "H": "absent",
            "Z": "live" if cfg["early"] else "absent",
            "A": "absent",
        }
        self.pn = {"I": set(), "H": set(), "A": set()}
        self.queue = []
        self.streams = {}
        self.crypto = {"I": Crypto(), "H": Crypto(), "A": Crypto()}
        self.received_total = 0
        self.open = True
        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0
        self.results = []
        # per-packet transaction state
        self.undo_streams = None
        self.undo_crypto = None
        self.saved_total = 0
        self.cur_level = None

    # -- bookkeeping -------------------------------------------------------

    def _add(self, ei, pi, status, reason, at, frame):
        self.results.append((ei, pi, {
            "event": ei, "packet": pi, "status": status, "reason": reason,
            "at_ms": at, "frame": frame,
        }))

    def _drop_queue(self, at, reason):
        for rec in self.queue:
            self._add(rec.ei, rec.pi, "dropped", reason, at, None)
        self.queue = []

    # -- event loop --------------------------------------------------------

    def run(self, events):
        for ei, ev in enumerate(events):
            t = ev["t"]
            if self.open and self.idle_ms and t >= self.last_activity + self.idle_ms:
                self._go_idle(ei)
            op = ev["op"]
            if op == "datagram":
                self._datagram(ei, ev, t)
            elif op == "key":
                if self.open:
                    self._key(ei, ev, t)
        for rec in self.queue:
            self._add(rec.ei, rec.pi, "buffered", "NO_KEYS", rec.arrival, None)
        self.queue = []

    def _go_idle(self, ei):
        deadline = self.last_activity + self.idle_ms
        self.open = False
        self.state = "idle"
        self.code = "IDLE_TIMEOUT"
        self.at_ms = deadline
        self.source = {"event": ei, "packet": None, "frame": None}
        self.peer_code = None
        self._drop_queue(deadline, "CONNECTION_CLOSED")

    def _datagram(self, ei, ev, t):
        pkts = ev["packets"]
        if self.open:
            bad = False
            for i in range(len(pkts) - 1):
                if pkts[i]["level"] == "A":
                    bad = True
                    break
            if bad:
                for pi in range(len(pkts)):
                    self._add(ei, pi, "dropped", "LAYOUT", t, None)
                return
        size = ev["bytes"]
        for pi, p in enumerate(pkts):
            if not self.open:
                self._add(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            level = p["level"]
            if level == "I" and size < 1200:
                self._add(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
                continue
            if level == "Z" and not self.early:
                self._add(ei, pi, "dropped", "EARLY_REJECTED", t, None)
                continue
            ks = self.keys[level]
            if ks == "discarded":
                self._add(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
                continue
            if ks == "absent":
                if len(self.queue) < self.buffer_packets:
                    self.queue.append(_Pkt(ei, pi, level, p["pn"], p["auth"],
                                            p["frames"], t))
                else:
                    self._add(ei, pi, "dropped", "BUFFER_FULL", t, None)
                continue
            self._process(_Pkt(ei, pi, level, p["pn"], p["auth"], p["frames"], t), t)

    def _key(self, ei, ev, t):
        level = ev["level"]
        if ev["action"] == "discard":
            self.keys[level] = "discarded"
            if self.queue:
                rest = []
                for rec in self.queue:
                    if rec.level == level:
                        self._add(rec.ei, rec.pi, "dropped", "KEYS_DISCARDED", t, None)
                    else:
                        rest.append(rec)
                self.queue = rest
        else:
            if self.keys[level] == "absent":
                self.keys[level] = "live"
                matched = []
                others = []
                for rec in self.queue:
                    if rec.level == level:
                        matched.append(rec)
                    else:
                        others.append(rec)
                self.queue = others
                for rec in matched:
                    if self.open:
                        self._process(rec, t)
                    else:
                        self._add(rec.ei, rec.pi, "dropped", "CONNECTION_CLOSED", t, None)

    # -- packet processing -------------------------------------------------

    def _process(self, rec, t):
        if not rec.auth:
            self._add(rec.ei, rec.pi, "dropped", "AUTH", t, None)
            return
        space = "A" if (rec.level == "A" or rec.level == "Z") else rec.level
        pn = rec.pn
        if pn in self.pn[space]:
            self._add(rec.ei, rec.pi, "duplicate", "DUPLICATE", t, None)
            return
        frames = rec.frames
        if not frames:
            self._fail("FRAME_ENCODING_ERROR", rec, t, None)
            return
        level = rec.level
        for fi, fr in enumerate(frames):
            ty = fr["type"]
            if ty == "UNKNOWN":
                self._fail("FRAME_ENCODING_ERROR", rec, t, fi)
                return
            if ty == "CLOSE":
                if fr["app"] and level != "Z" and level != "A":
                    self._fail("PROTOCOL_VIOLATION", rec, t, fi)
                    return
            elif level not in _ALLOWED[ty]:
                self._fail("PROTOCOL_VIOLATION", rec, t, fi)
                return
        self.undo_streams = {}
        self.undo_crypto = {}
        self.saved_total = self.received_total
        self.cur_level = level
        close = None
        for fi, fr in enumerate(frames):
            ty = fr["type"]
            if ty == "CLOSE":
                close = (fi, fr)
                break
            err = self._apply(fr, ty)
            if err is not None:
                self._rollback()
                self._fail(err, rec, t, fi)
                return
        self.pn[space].add(pn)
        self.last_activity = t
        self._add(rec.ei, rec.pi, "accepted", "OK", t, None)
        if close is not None:
            fi, fr = close
            code = "PEER_APPLICATION_CLOSE" if fr["app"] else "PEER_TRANSPORT_CLOSE"
            self._terminate_close(code, t, rec, fi, fr["code"])

    def _fail(self, code, rec, t, fi):
        self.open = False
        self.state = "closed"
        self.code = code
        self.at_ms = t
        self.source = {"event": rec.ei, "packet": rec.pi, "frame": fi}
        self.peer_code = None
        self._add(rec.ei, rec.pi, "error", code, t, fi)
        self._drop_queue(t, "CONNECTION_CLOSED")

    def _terminate_close(self, code, t, rec, fi, peer_code):
        self.open = False
        self.state = "closed"
        self.code = code
        self.at_ms = t
        self.source = {"event": rec.ei, "packet": rec.pi, "frame": fi}
        self.peer_code = peer_code
        self._drop_queue(t, "CONNECTION_CLOSED")

    # -- transaction helpers ----------------------------------------------

    def _get_stream(self, sid):
        st = self.streams.get(sid)
        if st is None:
            if sid not in self.undo_streams:
                self.undo_streams[sid] = None
            st = Stream(sid)
            self.streams[sid] = st
        elif sid not in self.undo_streams:
            self.undo_streams[sid] = (st, st.highest, st.final_size, st.reset,
                                      st.stopped, st.contig, dict(st.chunks))
        return st

    def _rollback(self):
        for sid, snap in self.undo_streams.items():
            if snap is None:
                self.streams.pop(sid, None)
            else:
                st = self.streams.get(sid)
                if st is not None:
                    st.highest, st.final_size, st.reset, st.stopped, st.contig, st.chunks = snap
        for level, snap in self.undo_crypto.items():
            st = self.crypto[level]
            st.highest, st.contig, st.chunks = snap
        self.received_total = self.saved_total

    # -- frame semantics ---------------------------------------------------

    def _apply(self, fr, ty):
        if ty == "ACK":
            return self._ack(fr)
        if ty == "CRYPTO":
            return self._crypto(fr)
        if ty == "STREAM":
            return self._stream(fr)
        if ty == "RESET_STREAM":
            return self._reset(fr)
        if ty == "STOP_SENDING":
            return self._stop(fr)
        return None  # PADDING / PING

    def _ack(self, fr):
        ranges = fr["ranges"]
        if not ranges:
            return "FRAME_ENCODING_ERROR"
        prev = None
        for pair in ranges:
            lo = pair[0]
            hi = pair[1]
            if lo > hi:
                return "FRAME_ENCODING_ERROR"
            if prev is not None and lo <= prev + 1:
                return "FRAME_ENCODING_ERROR"
            prev = hi
        sent = self.sent[self.cur_level]
        ns = len(sent)
        i = 0
        for pair in ranges:
            lo = pair[0]
            hi = pair[1]
            while i < ns and sent[i][1] < lo:
                i += 1
            cur = lo
            while cur <= hi:
                if i >= ns:
                    return "PROTOCOL_VIOLATION"
                sr = sent[i]
                if sr[0] > cur:
                    return "PROTOCOL_VIOLATION"
                if sr[1] < hi:
                    cur = sr[1] + 1
                    i += 1
                else:
                    cur = hi + 1
        return None

    def _crypto(self, fr):
        level = self.cur_level
        st = self.crypto[level]
        if level not in self.undo_crypto:
            self.undo_crypto[level] = (st.highest, st.contig, dict(st.chunks))
        data = bytes.fromhex(fr["data_hex"])
        off = fr["offset"]
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        if end > self.crypto_limit:
            return "CRYPTO_BUFFER_EXCEEDED"
        err = st.store(off, data, self.keep_first)
        if err is not None:
            return err
        if end > st.highest:
            st.highest = end
        st.advance()
        return None

    def _stream(self, fr):
        sid = fr["id"]
        m = sid & 3
        if m != 0 and m != 2:
            return "STREAM_STATE_ERROR"
        limit = self.max_bidi if m == 0 else self.max_uni
        if (sid >> 2) + 1 > limit:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        data = bytes.fromhex(fr["data_hex"])
        off = fr["offset"]
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        fs = st.final_size
        fin = fr["fin"]
        if fs is not None:
            if end > fs or (fin and end != fs):
                return "FINAL_SIZE_ERROR"
        if fin and end < st.highest:
            return "FINAL_SIZE_ERROR"
        if end > self.max_stream_data:
            return "FLOW_CONTROL_ERROR"
        new_high = end if end > st.highest else st.highest
        if self.received_total - st.highest + new_high > self.max_data:
            return "FLOW_CONTROL_ERROR"
        if not st.reset:
            err = st.store(off, data, self.keep_first)
            if err is not None:
                return err
        if new_high > st.highest:
            self.received_total += new_high - st.highest
            st.highest = new_high
        if fin:
            st.final_size = end
        st.advance()
        return None

    def _reset(self, fr):
        sid = fr["id"]
        m = sid & 3
        if m != 0 and m != 2:
            return "STREAM_STATE_ERROR"
        limit = self.max_bidi if m == 0 else self.max_uni
        if (sid >> 2) + 1 > limit:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        fs = fr["final_size"]
        if st.final_size is not None and st.final_size != fs:
            return "FINAL_SIZE_ERROR"
        if fs < st.highest:
            return "FINAL_SIZE_ERROR"
        if fs > self.max_stream_data:
            return "FLOW_CONTROL_ERROR"
        new_high = fs if fs > st.highest else st.highest
        if self.received_total - st.highest + new_high > self.max_data:
            return "FLOW_CONTROL_ERROR"
        if new_high > st.highest:
            self.received_total += new_high - st.highest
            st.highest = new_high
        st.final_size = fs
        st.reset = True
        return None

    def _stop(self, fr):
        sid = fr["id"]
        if sid & 3 != 0:
            return "STREAM_STATE_ERROR"
        if (sid >> 2) + 1 > self.max_bidi:
            return "STREAM_LIMIT_ERROR"
        st = self._get_stream(sid)
        st.stopped = True
        return None

    # -- output ------------------------------------------------------------

    def build(self, tid):
        ordered = sorted(self.results, key=lambda r: (r[0], r[1]))
        packets = [r[2] for r in ordered]
        conn = {
            "state": self.state,
            "code": self.code,
            "at_ms": self.at_ms,
            "source": self.source,
            "peer_code": self.peer_code,
            "last_activity_ms": self.last_activity,
        }
        keys = {
            "I": self.keys["I"],
            "H": self.keys["H"],
            "Z": self.keys["Z"],
            "A": self.keys["A"],
        }
        streams = []
        for sid in sorted(self.streams):
            st = self.streams[sid]
            streams.append({
                "id": sid,
                "highest": st.highest,
                "final_size": st.final_size,
                "reset": st.reset,
                "stopped": st.stopped,
                "delivered_hex": st.prefix_hex(),
            })
        crypto = []
        for lv in ("I", "H", "A"):
            st = self.crypto[lv]
            crypto.append({
                "level": lv,
                "highest": st.highest,
                "contiguous_hex": st.prefix_hex(),
            })
        return {
            "id": tid,
            "packets": packets,
            "connection": conn,
            "keys": keys,
            "received_total": self.received_total,
            "streams": streams,
            "crypto": crypto,
        }


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------

def _emit(obj):
    sys.stdout.write(json.dumps(obj))
    sys.stdout.write("\n")
    sys.stdout.flush()


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return 0
    try:
        doc = _parse(raw)
        _validate(doc)
    except Invalid:
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
        return 0
    try:
        results = []
        for tr in doc["traces"]:
            sim = Sim(tr["config"])
            sim.run(tr["events"])
            results.append(sim.build(tr["id"]))
        _emit({"version": 1, "results": results})
    except Exception as exc:  # pragma: no cover - defensive only
        sys.stderr.write("internal error: %r\n" % (exc,))
        sys.stdout.write('{"error":"INVALID_INPUT"}\n')
    return 0


if __name__ == "__main__":
    sys.exit(main())
